						error {
							type
							message
						}
					}
					... on ArmState {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						armStateValue
						error {
							type
							message
						}
					}
					... on Battery {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						error {
							type
							message
						}
