							type
							message
						}
					}
					... on Mode {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						error {
							type
							message
						}
						modeValue {
							value
						}
					}
					... on Lock {
						name
						timestamp
						timeOfSample
						timeOfLastChange
						accuracy
						type
						lockState
						error {
							type
							message
						}
					}
					... on Illuminance {
						name
						accuracy
						type
						timeOfSample
						timeOfLastChange
						error {
							type
							message
						}
						illuminanceValue {
							value
						}
					}
					... on Geolocation {
						name
						accuracy
						type
