						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						error {
							type
							message
						}
					}
					... on ToggleState {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						toggleStateValue
						error {
							type
							message
						}
					}
					... on ThermostatMode {
						name
						timestamp
						timeOfSample
						timeOfLastChange
						accuracy
						type
						thermostatModeValue
						error {
							type
							message
						}
					}
					... on TemperatureSensor {
						name
						timestamp
						timeOfSample
						timeOfLastChange
						accuracy
						type
						error {
							type
							message
						}
						value {
							value
							scale
						}
					}
					... on StatusCode {
						name
						type
						accuracy
						timeOfSample
						timeOfLastChange
