{"operationName":"SetEndpointFeatures","query":"
mutation SetEndpointFeatures ($input: SetEndpointFeaturesInput!) {
	setEndpointFeatures(setEndpointFeaturesInput: $input) {
		featureControlResponses {
			endpointId
			featureName
			instance
			featureOperationName
			payload
			code
			responsePayload {
				__typename
				... on CommissioningInformationReport {
					type
					value {
						commissioningInformation {
							__typename
							... on MatterCommissioningInformation {
								localProtocol
								protocolData {
									manualPairingCode
									commissioningWindowExpirationTimestamp
								}
							}
						}
					}
				}
				... on FabricList {
					type
					maxSupportedFabrics
					currentFabricCount
					fabrics {
						label
						fabricIndex
						fabricId
						vendorId
						isRemovable
					}
				}
				... on FabricRemoval {
					type
					fabric {
						fabricIndex
						fabricId
						vendorId
					}
				}
			}
		}
		errors {
			endpointId
			featureName
			instance
			featureOperationName
			payload
			code
			message
		}
	}
}
","variables":{"input":{"featureControlRequests":[{"endpointId":"synthetic-endpoint","entityId":"synthetic-endpoint","featureName":"power","featureOperationName":"turnOn","instance":"","payload":null}]}}}
